INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 100, 3001, 0.0, "ヤマト", "2024/10/31 12:00:00", 2, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 2.1, 130011, "2030/01/01 14:59:59", 3001100, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 101, 3001, 0.0, "ヤマト", "2024/10/31 12:00:00", 2, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 5.68, 130011, "2030/01/01 14:59:59", 3001101, 4);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 102, 3001, 0.0, "ヤマト", "2024/10/31 12:00:00", 1, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 0.0, 130011, "2030/01/01 14:59:59", 3001102, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 100, 3002, 0.0, "フブキ", "2024/10/31 12:00:00", 1, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 0.0, 130211, "2030/01/01 14:59:59", 3002100, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 101, 3002, 0.0, "フブキ", "2024/10/31 12:00:00", 1, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 0.0, 130211, "2030/01/01 14:59:59", 3002101, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 102, 3002, 0.0, "フブキ", "2024/10/31 12:00:00", 2, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 8.53, 130211, "2030/01/01 14:59:59", 3002102, 5);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 103, 3002, 0.0, "フブキ", "2024/10/31 12:00:00", 1, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 5.67, 130211, "2030/01/01 14:59:59", 3002103, 7);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 104, 3002, 0.0, "フブキ", "2024/10/31 12:00:00", 1, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 0.0, 130211, "2030/01/01 14:59:59", 3002104, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 300, 3004, 0.0, "フブキ", "2024/10/31 12:00:00", 3, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 0.0, 130211, "2030/01/01 14:59:59", 3002300, 3);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 301, 3005, 0.0, "フブキ", "2024/10/31 12:00:00", 7, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 0.0, 130211, "2030/01/01 14:59:59", 3002400, 7);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 200, 3003, 0.0, "フブキ", "2024/10/31 12:00:00", 1, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 4.4, 130211, "2030/01/01 14:59:59", 3003200, 2);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 201, 3003, 0.0, "フブキ", "2024/10/31 12:00:00", 7, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 0.0, 130211, "2030/01/01 14:59:59", 3003201, 7);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 202, 3003, 0.0, "フブキ", "2024/10/31 12:00:00", 2, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", 5.6, 130211, "2030/01/01 14:59:59", 3003202, 1);
